if(!exists('compute_limit_frontier'))library(creditratingsystem)
de_D<-'2023-01-01'
de_target<-function()list(event='default',horizon=365,time_unit='days',probability_measure='PHYSICAL',conditioning='initially_performing')
de_profile<-function()list(profile_id='p',version='1',known_at=de_D,currency='EUR')
de_offer<-function(id='a',amount=100)list(offer_id=id,version='1',known_at=de_D,currency='EUR',subject_id='s',amount=amount,tenor_days=365,assumption_reference='approved-scenario')
de_limit_profile<-function()c(de_profile(),list(target=de_target(),maximum_amount=300,maximum_ead=300,maximum_expected_loss=20,maximum_concentration=.5,concentration_denominator=1000,existing_group_exposure=100,tolerance=1e-12))
de_limit_offer<-function(id,amount,pd,cap=150)c(de_offer(id,amount),list(target=de_target(),pd=pd,lgd=.5,ead=amount,risk_conditioning='CONDITIONAL_ON_THIS_OFFER',risk_reference='model-frozen',affordability_status='AFFORDABLE',affordability_maximum_amount=cap,eligibility_status='ELIGIBLE'))
de_price_profile<-function()c(de_profile(),list(default_timing='BEFORE_DUE',prepayment_timing='AFTER_COUPON',funding_treatment='DISCOUNT_CURVE_ONLY',selection_assumption='QUOTE_CONDITIONED_INPUTS_NOT_CAUSAL'))
de_quote<-function()c(de_offer(),list(annual_rate=.1,target=de_target(),risk_conditioning='CONDITIONAL_ON_THIS_ACCEPTED_QUOTE',risk_reference='quote-conditioned',takeup_probability=.5,takeup_reference='declared-demand',upfront_fee=0,origination_cost=0,offer_cost=1,periods=list(list(payment_date='2024-01-01',scheduled_principal=100,conditional_default_probability=0,conditional_prepayment_probability=0,lgd=.4,recovery_date='2024-01-01',payment_discount_factor=1/1.1,recovery_discount_factor=1/1.1,servicing_cost=0,prepayment_fee=0))))
de_treatment_profile<-function()c(de_profile(),list(subject_id='s',baseline_id='no-action',baseline_present_value=20,identification='CONDITIONAL_SCENARIO_NOT_CAUSAL',allowed_actions=list('ARRANGEMENT')))
de_treatment<-function(id='a',df=1)list(treatment_id=id,version='1',known_at=de_D,subject_id='s',currency='EUR',action='ARRANGEMENT',prediction_reference='conditional-model',support_status='SUPPORTED',affordability_status='AFFORDABLE',eligibility_status='ELIGIBLE',uptake_probability=.5,offer_cost=1,accepted_upfront_cost=2,rejected_present_value=10,cashflows=list(list(cashflow_id='f',date='2024-01-01',expected_recovery=100,expected_cost=0,discount_factor=df)))
de_error<-function(code,expr){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),e$code==code)}
r<-compute_limit_frontier(list(de_limit_offer('a',100,.5),de_limit_offer('b',150,.1),de_limit_offer('c',200,.05)),de_limit_profile(),de_D)$value
stopifnot(identical(vapply(r$candidates,function(x)x$feasible,TRUE),c(FALSE,TRUE,FALSE)),r$candidates[[1]]$expected_loss==25,r$candidates[[2]]$expected_loss==7.5,identical(r$candidates[[3]]$failures,list('AFFORDABILITY_AMOUNT')),identical(r$frontier_offer_ids,list('b')),r$maximum_feasible_amount==150,identical(r$candidates[[2]]$binding_constraints,list('AFFORDABILITY_AMOUNT')))
rows<-list(de_limit_offer('a',100,.2,300),de_limit_offer('b',150,.1,300),de_limit_offer('c',200,.12,300));r<-compute_limit_frontier(rows,de_limit_profile(),de_D)$value;stopifnot(identical(r$frontier_offer_ids,list('b','c')));rows[[1]]['affordability_maximum_amount']<-list(NULL);stopifnot(!compute_limit_frontier(rows,de_limit_profile(),de_D)$value$candidates[[1]]$feasible);rows[[1]]$risk_conditioning<-'BASELINE';de_error('TARGET_MISMATCH',compute_limit_frontier(rows,de_limit_profile(),de_D))
q<-de_quote();q$offer_cost<-0;r<-compute_risk_based_price_grid(list(q),de_price_profile(),de_D)$value$candidates[[1]];stopifnot(abs(r$conditional_booked_npv)<1e-12,abs(r$expected_npv_per_offer)<1e-12,r$cashflows[[1]]$expected_interest==10)
q<-de_quote();q$periods[[1]]$conditional_default_probability<-.2;q$periods[[1]]$conditional_prepayment_probability<-.3;q$periods[[1]]$prepayment_fee<-2;r<-compute_risk_based_price_grid(list(q),de_price_profile(),de_D)$value$candidates[[1]]
stopifnot(abs(r$conditional_booked_npv-(100.6/1.1-100))<1e-12,abs(r$expected_npv_per_offer-(.5*(100.6/1.1-100)-1))<1e-12,abs(r$conditional_discounted_expected_loss-8/1.1)<1e-12,r$lifetime_pd==.2,r$prepayment_probability==.3,r$terminal_performing_probability==.5)
q$periods[[1]]$recovery_date<-'2025-01-01';q$periods[[1]]$recovery_discount_factor<-1/1.1^2;r<-compute_risk_based_price_grid(list(q),de_price_profile(),de_D)$value$candidates[[1]];stopifnot(abs(r$conditional_booked_npv-(88.6/1.1+12/1.1^2-100))<1e-12)
a<-de_quote();b<-a;b$offer_id<-'b';b$annual_rate<-.2;b$periods[[1]]$conditional_default_probability<-.8;r<-compute_risk_based_price_grid(list(a,b),de_price_profile(),de_D)$value$candidates;stopifnot(r[[2]]$annual_rate>r[[1]]$annual_rate,r[[2]]$expected_npv_per_offer<r[[1]]$expected_npv_per_offer)
q<-de_quote();q$target$horizon<-366;de_error('TARGET_MISMATCH',compute_risk_based_price_grid(list(q),de_price_profile(),de_D));q<-de_quote();q$periods[[1]]$scheduled_principal<-50;de_error('DECISION_PRICING_CONTRACT',compute_risk_based_price_grid(list(q),de_price_profile(),de_D));q<-de_quote();q$periods[[1]]$recovery_discount_factor<-.5;de_error('DECISION_PRICING_CONTRACT',compute_risk_based_price_grid(list(q),de_price_profile(),de_D))
a<-de_treatment();b<-de_treatment('b',.5);r<-evaluate_treatment_candidates(list(a,b),de_treatment_profile(),de_D)$value
stopifnot(r$candidates[[1]]$accepted_present_value==98,r$candidates[[1]]$expected_present_value==53,r$candidates[[2]]$expected_present_value==28,identical(r$feasible_ranking,list('a','b')));a$affordability_status<-'UNAFFORDABLE';r<-evaluate_treatment_candidates(list(a,b),de_treatment_profile(),de_D)$value;stopifnot(identical(r$feasible_ranking,list('b')),r$candidates[[1]]$expected_present_value==53);b$support_status<-'UNSUPPORTED';r<-evaluate_treatment_candidates(list(a,b),de_treatment_profile(),de_D)$value;stopifnot(r$status=='INFEASIBLE',is.null(r$candidates[[2]]$expected_present_value))
q<-de_quote();q$known_at<-'2023-01-02';de_error('DECISION_FUTURE_INPUT',compute_risk_based_price_grid(list(q),de_price_profile(),de_D));de_error('TARGET_MISMATCH',evaluate_treatment_candidates(list(de_treatment()),de_treatment_profile(),de_D,context=list(currency='USD')));de_error('DECISION_DUPLICATE',compute_limit_frontier(rep(list(de_limit_offer('a',100,.1)),2),de_limit_profile(),de_D))
cat('Native decision offer economics analytical cases PASS\n')
q<-de_quote();q$tenor_days<-730;q$target$horizon<-730;p<-q$periods[[1]];p$scheduled_principal<-40;p$conditional_default_probability<-.1;p$conditional_prepayment_probability<-.2;p$payment_discount_factor<-p$recovery_discount_factor<-1;p2<-p;p2$payment_date<-p2$recovery_date<-'2024-12-31';p2$scheduled_principal<-60;p2$conditional_default_probability<-.2;p2$conditional_prepayment_probability<-.1;q$periods<-list(p,p2);r<-compute_risk_based_price_grid(list(q),de_price_profile(),de_D)$value$candidates[[1]]
stopifnot(abs(r$lifetime_pd-.24)<1e-12,abs(r$prepayment_probability-.27)<1e-12,abs(r$terminal_performing_probability-.49)<1e-12,abs(r$cashflows[[1]]$discounted_net_cashflow-63)<1e-12,abs(r$cashflows[[2]]$discounted_net_cashflow-42)<1e-12,abs(r$conditional_booked_npv-5)<1e-12)

for(ctx in list(list(horizon=366),list(time_unit='years'),list(conditioning='other'))){de_error('TARGET_MISMATCH',compute_risk_based_price_grid(list(de_quote()),de_price_profile(),de_D,context=ctx));de_error('TARGET_MISMATCH',compute_limit_frontier(list(de_limit_offer('a',100,.1)),de_limit_profile(),de_D,context=ctx))}
